UPDATE trip_checklist_items SET is_carried_over = 1 WHERE trip_id = #{tripId} AND checklist_type = 'PRE_TRAVEL' AND is_completed = 0 AND is_carried_over = 0 AND is_deleted = 0 AND is_excluded = 0 AND (
(#{daysUntilTrip} <= 7 AND dday_stage = 'D30') OR (#{daysUntilTrip} <= 1 AND dday_stage IN ('D30', 'D7'))
)

mapper.select:
SELECT EXISTS (SELECT 1
               FROM trip_checklist_items
               WHERE id = #{itemId}
                 AND trip_id = #{tripId}
                 AND is_deleted = 0
                 AND is_excluded = 0)

